draw((length+width*cos(angle1),width*sin(angle1))--(length+width*cos(angle1),0)--(width*cos(angle2),width*sin(angle2))--(width*cos(angle2),0)--cycle,linewidth(1));
draw((length+width*cos(angle1),width*sin(angle1))--(length+width*cos(angle1),0)--(length+width*cos(angle1)+width*cos(angle2),width*sin(angle2))--(length+width),linewidth(1));
