label("2",(width*cos(angle2/2),width*sin(angle2/2)),SW);
label("60",(length/2+width*cos(angle/2),width*sin(angle/2)+width/4),NE);
label("30",(length+width*cos(angle1)+length/2+width*cos(angle/2),width*sin(angle2/2)+width/4),NE);
